// Generated by commitar-oc (adapters/opencode/templates/vault-core.mjs). Do not edit.
// Writes AI-first notes (see the vault's references/ai-first-rules.md) deterministically.
import { writeFileSync, mkdirSync, existsSync } from "node:fs"
import { join } from "node:path"

const ASCII = { "—": " - ", "–": " - ", "‘": "'", "’": "'", "“": '"', "”": '"', "…": "...", " ": " " }
const SECRETS = [
  /sk-[A-Za-z0-9_-]{20,}/, /AKIA[0-9A-Z]{16}/, /-----BEGIN [A-Z ]*PRIVATE KEY-----/, /gh[pousr]_[A-Za-z0-9]{30,}/,
  /(password|passwd|secret|api[_-]?key|token)\s*[:=]\s*["']?[^\s"']{8,}/i,
]
const KINDS = {
  spec: { folder: "Architecture", type: "architecture", file: (p) => `${p}-spec.md`, why: "Summary of the project spec, saved after the SPEC phase. The canonical spec lives in the project repo; this copy is for retrieval across projects." },
  devlog: { folder: "Dev Logs", type: "devlog", file: (p, d, t) => `${d}-${p}-${t}.md`, why: "Engineering log entry: what was done, decisions, and next steps." },
}

export const slug = (s) => String(s).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 60)
const toAscii = (s) => s.replace(/[—–‘’“”… ]/g, (c) => ASCII[c])

export function saveNote({ vaultPath, kind, project, title, summary, now = new Date() }) {
  const k = KINDS[kind]
  if (!k) return { ok: false, error: `unknown kind "${kind}" (use ${Object.keys(KINDS).join("|")})` }
  if (!existsSync(join(vaultPath, "_CLAUDE.md"))) return { ok: false, error: `${vaultPath} is not an initialized vault (no _CLAUDE.md). Run: commitar-oc vault init` }
  const p = slug(project), t = slug(title)
  if (!p || !t) return { ok: false, error: "project and title must contain letters or digits" }
  const text = toAscii(String(summary).trim())
  if (!text) return { ok: false, error: "summary is empty" }
  for (const re of SECRETS) if (re.test(text)) return { ok: false, error: "summary looks like it contains a secret; nothing was written" }

  const date = now.toISOString().slice(0, 10)
  const dir = join(vaultPath, k.folder)
  mkdirSync(dir, { recursive: true })
  const path = join(dir, k.file(p, date, t))
  const note = `---\ndate: ${date}\ntype: ${k.type}\ntags:\n  - ${k.type}\n  - ${p}\nai-first: true\nproject: ${p}\nsource: commitar-oc\n---\n\n# ${toAscii(String(title).trim())}\n\n## For future agent\n\n${k.why}\n\n${text}\n`
  writeFileSync(path, note)
  return { ok: true, path }
}
